import React, { useEffect, useState } from "react";
import Layout from "../components/Layout";
import api from "../api/axios";
import Modal from "../components/Modal";
import { useNavigate } from "react-router-dom";
import "./DuplicateRequestPage.css";

function DuplicateRequestPage() {
  const [cards, setCards] = useState([]);
  const [rows, setRows] = useState([]);
  const [form, setForm] = useState({ id_card_id: "", reason: "", remarks: "" });
  const [modal, setModal] = useState({ show: false, type: "success", message: "" });
  const [loading, setLoading] = useState(false);
  const [selectedCard, setSelectedCard] = useState(null);
  const navigate = useNavigate();

  const load = async () => {
    try {
      const cardsRes = await api.get("/api/id-cards/");
      const rowsRes = await api.get("/api/duplicate-requests/");
      setCards(cardsRes.data);
      setRows(rowsRes.data);
    } catch (error) {
      console.error("Error loading data:", error);
      setModal({
        show: true,
        type: "error",
        message: "Failed to load data. Please try again."
      });
    }
  };

  useEffect(() => { load(); }, []);

  const submit = async (e) => {
    e.preventDefault();
    setLoading(true);

    // Validate form before submission
    if (!form.id_card_id) {
      setModal({
        show: true,
        type: "error",
        message: "Please select an ID card"
      });
      setLoading(false);
      return;
    }

    if (!form.reason.trim()) {
      setModal({
        show: true,
        type: "error",
        message: "Please provide a reason for the duplicate request"
      });
      setLoading(false);
      return;
    }

    try {
      await api.post("/api/duplicate-requests/", form);
      setForm({ id_card_id: "", reason: "", remarks: "" });
      setModal({
        show: true,
        type: "success",
        message: "Duplicate request created successfully!"
      });
      load();
    } catch (error) {
      console.error("Duplicate request error:", error);
      setModal({
        show: true,
        type: "error",
        message: "Failed to create duplicate request. Please try again."
      });
    } finally {
      setLoading(false);
    }
  };

  const approve = async (id) => {
    try {
      await api.post(`/api/duplicate-requests/${id}/approve`);
      setModal({
        show: true,
        type: "success",
        message: "Duplicate request approved successfully!"
      });
      load();
    } catch (error) {
      console.error("Approval error:", error);
      setModal({
        show: true,
        type: "error",
        message: "Failed to approve request. Please try again."
      });
    }
  };

  const reject = async (id) => {
    try {
      await api.post(`/api/duplicate-requests/${id}/reject`);
      setModal({
        show: true,
        type: "success",
        message: "Duplicate request rejected successfully!"
      });
      load();
    } catch (error) {
      console.error("Rejection error:", error);
      setModal({
        show: true,
        type: "error",
        message: "Failed to reject request. Please try again."
      });
    }
  };

  const viewCard = (cardId) => {
    navigate(`/id-cards`);
  };

  const getCardDetails = (cardId) => {
    return cards.find(card => card.id === cardId);
  };

  return (
    <Layout>
      <div className="dup-grid">
        <div className="page-card">
          <h2>Create Duplicate Request</h2>
          <form className="dup-form" onSubmit={submit}>
            <label>ID Card</label>
            <select className="form-control" value={form.id_card_id} onChange={(e) => setForm({ ...form, id_card_id: e.target.value })}>
              <option value="">Select card</option>
              {cards.map((card) => (
                <option key={card.id} value={card.id}>{card.card_number}</option>
              ))}
            </select>
            <label>Reason</label>
            <input className="form-control" value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })} />
            <label>Remarks</label>
            <textarea className="form-control" rows="4" value={form.remarks} onChange={(e) => setForm({ ...form, remarks: e.target.value })}></textarea>
            <button className="primary-btn" type="submit">Save Request</button>
          </form>
        </div>

        <div className="page-card">
          <h2>Duplicate Requests</h2>
          <table className="data-table">
            <thead><tr><th>ID</th><th>Card ID</th><th>Reason</th><th>Status</th><th>Approve</th></tr></thead>
            <tbody>
              {rows.map((item) => (
                <tr key={item.id}>
                  <td>{item.id}</td>
                  <td>{item.id_card_id}</td>
                  <td>{item.reason}</td>
                  <td>{item.status}</td>
                  <td><button className="primary-btn" onClick={() => approve(item.id)}>Approve</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </Layout>
  );
}

export default DuplicateRequestPage;
